let raw = ""; for await (const c of process.stdin) raw += c;
let ev = {}; try { ev = JSON.parse(raw); } catch { process.exit(0); }
const i = ev.tool_input || {};
const target = i.file_path || i.path || i.notebook_path || "";
const cmd = i.command || "";

const deny = (reason) => {
  process.stdout.write(JSON.stringify({ hookSpecificOutput: {
    hookEventName: "PreToolUse", permissionDecision: "deny", permissionDecisionReason: reason } }));
  process.exit(2);
};

// dist/ is generated by build/build.mjs from content/ + theme/ + templates/.
if (/(^|\/)dist\//.test(target))
  deny("dist/ is generated. Edit the source in content/, theme/ or templates/, then run `npm run build` — a hand edit here is destroyed by the next build.");

// The site publicly promises corrections are appended and never silently patched.
if (/content\/corrections\.json$/.test(target))
  deny("corrections.json is append-only — the colophon promises readers it is never silently patched. Use `npm run correct -- \"Title.\" \"Body.\"` instead.");

// Same two rules, via the shell.
if (cmd) {
  if (/(>|>>|tee|sed -i|truncate|rm)\s+[^|;&]*dist\//.test(cmd))
    deny("That writes to dist/, which is generated. Change the source and run `npm run build`.");
  if (/(>|>>|tee|sed -i|truncate|rm)\s+[^|;&]*content\/corrections\.json/.test(cmd))
    deny("corrections.json is append-only. Use `npm run correct` — it cannot rewrite or remove what is already printed.");
}
process.exit(0);
